#!/usr/bin/env Rscript
suppressPackageStartupMessages(library(data.table))
a<-commandArgs(TRUE);project<-normalizePath(if(length(a))a[1]else'paper19opp-revision2');rb<-file.path(project,'upr_robustness');out<-file.path(project,'supplementary_data/upr_readout_robustness');dir.create(out,recursive=TRUE,showWarnings=FALSE);idx<-list()
add<-function(from,folder='',name=basename(from),description=''){
 stopifnot(file.exists(from));relative<-if(nzchar(folder))file.path(folder,name)else name;to<-file.path(out,relative);dir.create(dirname(to),recursive=TRUE,showWarnings=FALSE);stopifnot(file.copy(from,to,overwrite=TRUE));d<-fread(to);for(nm in names(d))if(is.character(d[[nm]]))stopifnot(!any(grepl('/Users/|/Volumes/',d[[nm]]),na.rm=TRUE));idx[[length(idx)+1L]]<<-data.table(file=relative,rows=nrow(d),columns=ncol(d),description=description)
}
sp<-file.path(rb,'specificity');md<-file.path(rb,'modules')
for(f in c('fixed_target_panels.tsv','all_fixed_panel_signature_effects.tsv.gz','primary80_rank_associations.tsv','secondary160_direction_consistency.tsv','chance_adjusted_direction_agreement.tsv','all320_minimal_covariate_sensitivities.tsv','study_balanced_signed_effect_summary.tsv','paired_full_disjoint_unique_specification_differences.tsv','paired_Frangieh_context_differences.tsv','readout_specificity_availability.tsv','all_fixed_library_real_null_readout_metrics.tsv.gz','fixed_library_readout_specificity_calibration.tsv','equal_depth_signature_summaries.tsv','shared_GEM_technical_signature_intervals.tsv','Hallmark94_identifier_sensitivity.tsv','Hallmark90_94_paired_gene_effects.tsv.gz','sequencing_depth_covariates.tsv','sequencing_depth_covariate_schema.tsv','sequencing_depth_schema_availability.tsv','sequencing_depth170_conditional_associations.tsv','sequencing_depth_model_inputs.tsv.gz'))add(file.path(sp,f),description='Complete fixed-panel curated-readout result or explicitly named conditional sensitivity; no post-outcome reselected target list')
for(f in c('locked_axis_definitions.tsv','locked_memberships.tsv','hierarchy_and_overlap.tsv','target_functional_annotations.tsv','target_functional_stratum_counts.tsv','original_Hallmark_UPR_full.tsv','Hallmark_disjoint_measured_exclusion.tsv','null100_per_readout_memberships.tsv.gz','null_matching_accounting.tsv','source_NTC_expression_detection_bins.tsv'))add(file.path(md,f),'definitions',description='Authoritative full/disjoint/unique gene membership or source-only negative-control definition and availability')
add(file.path(md,'canonical_Hallmark94/fixed_canonical_members.tsv'),'definitions',description='Deterministic identifier-only94-member sensitivity; original90 assays/ranks remain unchanged')
for(f in list.files(file.path(sp,'figure_source_data'),pattern='\\.tsv$',full.names=TRUE))add(f,'figure_source_data',description='Exact plotted final readout robustness values')
rk<-file.path(rb,'ranking')
for(f in c('source_quintile_membership.tsv','quintile_group_summaries.tsv','quintile_trend_estimates.tsv','joint_Holm7_tests.tsv','quintile_adjacent_simultaneous_intervals.tsv','quintile_ordered_draw_fractions.tsv','fixed_ranking_metrics.tsv','paired_method_differences.tsv','all100_null_metric_calibration.tsv','all100_fixed_null_ranking_metrics.tsv','fixed_background_positive_enrichment.tsv','uniform_random_ranking_reference.tsv','ranking_exact_equal100_sensitivities.tsv','quintile_exact_equal100_sensitivities.tsv','primary_quintile_projection_trend_estimates.tsv'))add(file.path(rk,f),'ranking',description='Previously fixed source groups/lists; retrospective quintile or ranking robustness with no validation-guided reranking')
for(f in c('source_alternative_Top10_Top20.tsv','source_rank_stability_vs_current.tsv','source_alternative_matching_coverage.tsv','alternative_readout_fixed_list_metrics.tsv','alternative_priority_paired_comparisons.tsv','alternative_fixed_background_gap_intervals.tsv','parent_specific_fixed_mode_null_calibration.tsv','parent_specific_null_list_metrics.tsv','alternative_readout_current_quintile_projection.tsv'))add(file.path(rk,'alternative_definitions',f),'ranking/alternative_definitions',description='Source-only alternate definition rankings frozen before corresponding scored RPE1 summaries; descriptive comparison, no additional P family')
for(f in c('canonical94_current_fixed_list_metrics.tsv','canonical94_paired_current_method_comparisons.tsv','canonical94_current_quintile_groups.tsv','canonical94_current_quintile_trends.tsv','canonical94_current_matched_gap_intervals.tsv'))add(file.path(rk,'canonical94_projection',f),'ranking/canonical94_projection',description='Identifier-only94 outcome projection of original90 source groups/lists; no94 ranking or new formal test')
for(f in c('depth_adjusted_fixed_matched_gaps.tsv','fixed_list_depth_balance.tsv','depth_model_coefficients.tsv'))add(file.path(rk,'depth_diagnostic',f),'ranking/depth_diagnostic',description='Descriptive recorded-UMI conditional continuous fixed-list matched gaps; no new P value, adjusted Precision or reranking')
f<-file.path(rk,'ranking_figure_random_reference_source.tsv');if(file.exists(f))add(f,'figure_source_data',description='Exact uniform and matched-null reference summaries in the ranking robustness figure')
f<-file.path(rb,'all87_additional_primary_tests.tsv');if(file.exists(f))add(f,description='Additional globalBH87 sensitivity across the unchanged Holm7 and BH80 primary families; not a replacement family')
index<-rbindlist(idx);stopifnot(!anyDuplicated(index$file));fwrite(index,file.path(out,'table_index.tsv'),sep='\t')
oldindex<-file.path(project,'supplementary_data/table_index.tsv');if(file.exists(oldindex)){old<-fread(oldindex);old<-old[!startsWith(file,'upr_readout_robustness/')];new<-copy(index);new[,file:=file.path('upr_readout_robustness',file)];fwrite(rbindlist(list(old,new),use.names=TRUE,fill=TRUE),oldindex,sep='\t')}
cat(nrow(index),'curated-readout tables exported; ',sum(file.info(file.path(out,index$file))$size),'bytes.\n')
